Example usage:

```ts
import { Redwood } from "@redwood/sdk";

const client = new Redwood({ apiKey: process.env.REDWOOD_API_KEY! });

// Create a shadow experiment attached to an existing route rollout
const exp = await client.shadowExperiments.create({
  routeId: "route_3d8c...",
  name: "llama3.1-70b-q4-canary-shadow",
  samplingRate: 0.02,
  control: { model: "llama-3.1-70b" },
  shadows: [{ model: "llama-3.1-70b", quantization: "int4" }],
});

// Query aggregate deltas (cursor-based pagination where applicable)
const aggregates = await client.shadowExperiments.getAggregates(exp.id, {
  window: "1h",
  filter: { segment: "route", outcome: "scored" },
});

// Iterate examples with cursor pagination
for await (const ex of client.shadowExperiments.iterateExamples(exp.id, { pageSize: 50 })) {
  console.log(ex.requestFingerprint, ex.metrics.formatAdherence);
}
```
